*{box-sizing:border-box}body{margin:0;background:#070a0f;color:#f3f6fb;font-family:system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1150px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;align-items:center}header b{font-size:23px}header span{opacity:.5}header small{display:block;color:#8d98a8;font-size:11px}.hero{padding:38px 0 22px}.hero h1{font-size:42px;margin:0 0 8px}.hero p,.muted{color:#a5afbe}.card{background:#11161f;border:1px solid #273142;border-radius:18px;padding:18px;margin-bottom:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;color:#9faaba;font-size:12px;margin-top:9px}input,textarea,select{width:100%;background:#080c12;color:#fff;border:1px solid #303a4b;border-radius:10px;padding:11px;margin-top:5px;font:inherit}textarea{min-height:120px;resize:vertical}button{width:100%;background:#fff;color:#080a0f;border:0;border-radius:11px;padding:13px;font-weight:900;margin-top:12px;cursor:pointer}.file{font-size:12px;background:#080c12;border-radius:8px;padding:8px;margin-top:5px;color:#b9c2ce}.job{border:1px solid #2a3546;border-radius:13px;padding:14px;margin:10px 0}.jobtop{display:flex;justify-content:space-between}.tag{font-size:11px;color:#8fe5c3}.progress{height:7px;background:#252d39;border-radius:99px;margin:10px 0;overflow:hidden}.bar{height:100%;width:0;background:#9ee7cc}.pill{display:inline-block;padding:5px 8px;border-radius:99px;background:#1b2330;font-size:11px;color:#b8c2d0;margin:3px}.link{color:#9ee7cc;text-decoration:none}.danger{color:#ffaaa8}@media(max-width:800px){.grid{grid-template-columns:1fr}.hero h1{font-size:32px}}
